import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in); int workers=s.nextInt(),iterations=s.nextInt(); AtomicInteger count=new AtomicInteger(); List<Thread> threads=new ArrayList<>(); for(int w=0;w<workers;w++)threads.add(new Thread(()->{for(int i=0;i<iterations;i++)count.incrementAndGet();})); threads.forEach(Thread::start); for(Thread t:threads)t.join(); System.out.println(count.get()); } }

